files.content:
html,
body {
  height: 100%;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-width: 850px;
  margin: 0;
  color: #5f0dee;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
}

.banner {
  width: 100%;
  padding: 50px;
  background-color: #feafe8;
}

.banner-link {
  color: inherit;
}

.banner-button {
  border: 1px solid currentColor;
  padding: 10px 45px;
  color: #5f0dee;
  font-family: inherit;
  font-weight: 800;
  font-size: inherit;
  text-transform: uppercase;
  background-color: transparent;
}

h2 {
  margin-top: 0;
}

/* Ниже будут ховер-эффект для кнопки */

.banner-button:hover {
  color: #fff;
  background-color: #5f0dee;
}

.banner-link:hover {
  text-decoration: none;
  color: #fd24af;
}
